<script setup lang="ts">
/**
 * Dropzone plus a file list with upload states (`design/components/file-upload.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/file-upload.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, shallowRef, useTemplateRef, watch } from 'vue'

import {
  Icon,
  agentMember,
  focusAfterListRemoval,
  formatBytes,
  gateFiles,
  useListening,
  type FileRejection,
} from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/file-upload.module.css'
import FileUploadRow from './FileUploadRow.vue'

export type FileUploadStatus = 'uploading' | 'done' | 'error'

export interface FileUploadItem {
  id: string
  name: string
  size?: number
  status: FileUploadStatus
  progress?: number
  message?: string
}

export interface FileUploadProps {
  /**
   * The native syntax (`.pdf`, `image/*`, `application/pdf`), applied to drops too.
   */
  accept?: string
  ariaDescribedby?: string
  /**
   * Set by FormField. Set it directly only when there is no visible label.
   */
  ariaLabel?: string
  ariaLabelledby?: string
  ariaRequired?: boolean
  disabled?: boolean
  /**
   * Always controlled, because the list and what happens to it are the app's state.
   */
  files?: FileUploadItem[]
  hint?: string
  invalid?: boolean
  /**
   * The app's size ceiling, in bytes. A file over it never reaches `onFilesAdd`.
   */
  maxSize?: number
  /**
   * All control and announcement text, localized by the application.
   */
  messages?: {
    retry: string
    remove: (name: string) => string
    progress: (name: string) => string
    announcement: (file: FileUploadItem) => string
    formatSize: (bytes: number) => string
  }
  /**
   * When `false`, a drop of several files keeps the first that passes and refuses the rest.
   */
  multiple?: boolean
  /**
   * Set on the hidden picker, for a native form post.
   */
  name?: string
  title?: string
}

defineOptions({ name: 'FileUpload', inheritAttrs: false, controlKind: 'group' })

const props = withDefaults(defineProps<FileUploadProps>(), {
  ariaRequired: undefined,
  disabled: false,
  files: () => [],
  invalid: false,
  messages: () => ({
    retry: 'Retry',
    remove: (name: string) => `Remove ${name}`,
    progress: (name: string) => `${name} upload progress`,
    announcement: (file: FileUploadItem) =>
      file.status === 'done'
        ? `${file.name} uploaded`
        : file.status === 'error'
          ? file.message === undefined
            ? `${file.name} failed`
            : `${file.name} failed: ${file.message}`
          : '',
    formatSize: formatBytes,
  }),
  multiple: true,
  title: 'Drop files or click to browse',
})
const emit = defineEmits<{
  filesAdd: [files: File[]]
  reject: [rejections: FileRejection[]]
  remove: [id: string]
  retry: [id: string]
}>()
const listening = useListening()
const dragover = ref(false)
const pressed = ref(null as { id: string; at: number } | null)
const picker = useTemplateRef<HTMLElement>('picker')
const root = useTemplateRef<HTMLElement>('root')
const rowList = useTemplateRef<HTMLElement>('rowList')
const zone = useTemplateRef<HTMLElement>('zone')
const zoneState = computed(() => (dragover.value ? 'dragover' : 'idle'))
const rowOf = computed(
  () => (id: string | undefined) =>
    id === undefined
      ? null
      : (rowList.value?.children[rows.value.findIndex((row) => row.key === id)] ?? null),
)
const removeControl = computed(
  () => (row: Element | null) =>
    row === null ? null : ([...row.querySelectorAll<HTMLElement>('button')].pop() ?? null),
)
const add = computed(
  () => (list: FileList | null | undefined) =>
    !props.disabled &&
    list != null &&
    list.length > 0 &&
    ((gate) => (
      gate.accepted.length > 0 && emit('filesAdd', gate.accepted),
      gate.rejected.length > 0 && emit('reject', gate.rejected)
    ))(
      gateFiles(Array.from(list), {
        accept: props.accept,
        multiple: props.multiple,
        maxSize: props.maxSize,
      }),
    ),
)
const rowsOf = () => props.files
const rowsKey = (file: FileUploadItem) => file.id
const rowsLeaving = shallowRef<
  { key: string; item: ReturnType<typeof rowsOf>[number]; at: number }[]
>([])
watch(
  rowsOf,
  (now, before) => {
    const kept = new Set(now.map(rowsKey))
    const leaving = rowsLeaving.value.filter((entry) => !kept.has(entry.key))
    before.forEach((item, at) => {
      const key = rowsKey(item)
      if (!kept.has(key) && !leaving.some((entry) => entry.key === key))
        leaving.push({ key, item, at })
    })
    rowsLeaving.value = leaving
  },
  { flush: 'sync' },
)
const rows = computed(() => {
  const entries = rowsOf().map((item) => ({ item, key: rowsKey(item), open: true, done: () => {} }))
  for (const entry of [...rowsLeaving.value].sort((a, b) => a.at - b.at))
    entries.splice(Math.min(entry.at, entries.length), 0, {
      item: entry.item,
      key: entry.key,
      open: false,
      done: () => {
        rowsLeaving.value = rowsLeaving.value.filter((other) => other.key !== entry.key)
      },
    })
  return entries
})
const effect1 = () => {
  pressed.value = focusAfterListRemoval(
    pressed.value,
    props.files.map((file) => file.id),
    (at) => removeControl.value(rowOf.value(props.files[at]?.id)),
    zone.value,
    pressed.value === null ? null : rowOf.value(pressed.value.id),
  )
}
watch(() => props.files, effect1, { flush: 'post' })
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'FileUpload',
    element: () => zone.value,
    state: () => ({
      files: props.files.map((file) => ({ ...file })),
      rows: props.files.map((file) => ({ id: file.id, label: file.name })),
      disabled: props.disabled,
      invalid: props.invalid,
    }),
    actions: {
      remove: { argument: 'id', run: (value) => emit('remove', value) },
      retry: {
        argument: 'id',
        run: (value) =>
          (() => {
            if (listening.retry !== true) throw new Error('The field offers no retry.')
            if (props.files.find((file) => file.id === value)?.status !== 'error')
              throw new Error('Only a failed upload is retried.')
            emit('retry', value)
          })(),
      },
    },
    withholds: () => root.value,
  })
  release2 = () => {
    ran()
  }
}
onMounted(effect2)
onBeforeUnmount(() => release2?.())
</script>

<template>
  <div
    ref="root"
    :class="styles.root"
    :data-state="zoneState"
    :data-disabled="disabled ? '' : undefined"
    :data-invalid="invalid ? '' : undefined"
    data-member="file-upload"
  >
    <!-- dropzone -->
    <button
      ref="zone"
      :class="styles.zone"
      type="button"
      :disabled="disabled"
      :data-state="zoneState"
      :data-disabled="disabled ? '' : undefined"
      :data-invalid="invalid ? '' : undefined"
      :aria-label="ariaLabel"
      :aria-labelledby="ariaLabelledby"
      :aria-describedby="ariaDescribedby"
      :aria-required="ariaRequired"
      :aria-invalid="invalid ? true : undefined"
      @click="picker?.click()"
      @dragover="($event.preventDefault(), !disabled && (dragover = true))"
      @dragleave="
        !($event.currentTarget as HTMLElement).contains($event.relatedTarget as Node | null) &&
        (dragover = false)
      "
      @drop="($event.preventDefault(), (dragover = false), add($event.dataTransfer?.files))"
    >
      <Icon name="upload" size="lg" />
      <!-- title -->
      <span :class="styles.title">
        {{ title }}
      </span>
      <!-- hint -->
      <span v-if="hint !== undefined" :class="styles.hint">
        {{ hint }}
      </span>
    </button>
    <!-- picker -->
    <input
      ref="picker"
      :class="styles.picker"
      type="file"
      :accept="accept"
      :multiple="multiple"
      :name="name"
      :disabled="disabled"
      tabindex="-1"
      @change="
        (add(($event.target as HTMLInputElement).files),
        (($event.target as HTMLInputElement).value = ''))
      "
    />
    <!-- list -->
    <ul v-if="files.length > 0" ref="rowList" :class="styles.list">
      <template v-for="row in rows" :key="row.key">
        <FileUploadRow
          :file="row.item"
          :open="row.open"
          :size="row.item.size === undefined ? undefined : messages.formatSize(row.item.size)"
          :retryable="listening.retry === true"
          :retryLabel="messages.retry"
          :removeLabel="messages.remove(row.item.name)"
          :progressLabel="messages.progress(row.item.name)"
          @retry="emit('retry', row.item.id)"
          @remove="
            ((pressed = {
              id: row.item.id,
              at: files.findIndex((file) => file.id === row.item.id),
            }),
            emit('remove', row.item.id))
          "
          @done="row.done()"
        />
      </template>
    </ul>
    <!-- reader -->
    <span :class="styles.reader" aria-live="polite">
      <template v-for="file in files" :key="file.id">
        <span>
          {{ messages.announcement(file) }}
        </span>
      </template>
    </span>
  </div>
</template>
